// === Tab: mySketch ===
OPC.slider('curliness', 1, 0, 3);
OPC.slider('velocity', 1, 0.5, 10);
OPC.toggle('screenshot', false);

let img;
let particles = [];
let edgeColour;

function preload(){
	img = loadImage("https://openprocessing.org/sketch/2026104/files/IMG_1241.JPG");
}

function setup() {
	createCanvas(1112, 834);
	img.resize(width, 0);
	background(255);


	colorMode(HSB, 255);

	edgeColour = color(random(255), 255, 255, 10);

	for(let i = 0; i < 600; i++){
		particles[i] = new Particle(edgeColour, curliness);
	}
}



function draw() {
	if (screenshot == true){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
		screenshot = false;
	}

	for(let i = 0; i < particles.length; i++){


    if(particles[i].pos.y < 0 || particles[i].pos.y > height 
			                        || particles[i].pos.x < 0 
			                        || particles[i].pos.x > width)
		{

      particles[i] = new Particle(edgeColour);
    }

    particles[i].update(velocity);
    particles[i].show();
  }
}



// === Tab: tab2 ===
class Particle{

	constructor(){

		colorMode(RGB, 255);


		this.rand = random(1);


		this.pos = createVector(0, random(height));
		//this.pos = createVector(random(width), random(height));
		this.vel = createVector(1, 0);
		//this.vel.rotate(random(TWO_PI));

		this.c = color(0);
	}

	update(velocity){

		this.past = createVector(this.pos.x, this.pos.y);

		this.pos.add(p5.Vector.mult(this.vel, velocity));
		this.c = 0;

		let ratio = brightness(img.get(int(this.pos.x), int(this.pos.y))) / 255;

		this.vel.rotate(random(-HALF_PI * pow(ratio, 3-curliness), HALF_PI * pow(ratio, 3-curliness)));


		this.c = color(map(ratio, 0, 1, 0, red(edgeColour)),  
											 map(ratio, 0, 1, 0, green(edgeColour)),
											 map(ratio, 0, 1, 0, blue(edgeColour)),
										   200 - ratio * 255);

	}

	show(){


		stroke(this.c);

		line(this.pos.x, this.pos.y, this.past.x, this.past.y);
	}

}

